#!/usr/bin/env python3
"""R6 directed sources. Expected C sites are transcribed from ADR/B, not generated by the binary."""

import argparse
import hashlib
import json
import os
from pathlib import Path
import subprocess
import tempfile


# All sources are ASCII without BOM or final newline. A null expected list means
# the source is exploratory until its exact original/expected is recovered.
CASES = {
    "B_M1": ("fn Main(){var q=[];var r=[];let b=q[0];(if true then [q] else (if true then [1] else q));r=q;q=[1];}", [("NX-E1303", 76, 79)]),
    "B_M2": ("fn Main(){var q=[];var r=[];let z=r[0];let a=(if true then r[0] else (if true then q else r));r=q;r=[true];}", [("NX-E0103", 16, 18)]),
    "planned": ("fn Main(){let x=1;var q=[];var s=[];let a=[s[x],(if 0 then true else q),(if x then q else s)];q=[true];s=[[true]];}", [("NX-E0102", 52, 53), ("NX-E1303", 69, 70), ("NX-E0102", 76, 77), ("NX-E0102", 106, 112)]),
    "X_02": ("fn Main(){let a:I64=(if true then 1 else (if 0 then true else 3));}", [("NX-E0102", 45, 46), ("NX-E0102", 52, 56)]),
    # A's equivalents of B's six external-context shapes. They are not the
    # missing original X-03..X-08 files from B's deleted temporary directory.
    "X_03_array_annotation_equiv": ("fn Main(){let a:Array<I64>=(if true then [1] else (if 0 then [true] else [3]));}", [("NX-E0102", 54, 55), ("NX-E0102", 62, 66)]),
    "X_04_argument_equiv": ("fn F(x:view I64){}fn Main(){F((if true then 1 else (if 0 then true else 3)));}", [("NX-E0102", 55, 56), ("NX-E0102", 62, 66)]),
    "X_05_return_equiv": ("fn F()->I64{return (if true then 1 else (if 0 then true else 3));}fn Main(){F();}", [("NX-E0102", 44, 45), ("NX-E0102", 51, 55)]),
    "X_06_operand_equiv": ("fn Main(){let a=1+(if true then 1 else (if 0 then true else 3));}", [("NX-E0102", 43, 44), ("NX-E0102", 50, 54)]),
    "X_07_three_levels_equiv": ("fn Main(){let a:I64=(if true then (if true then 1 else 2) else (if 0 then true else 3));}", [("NX-E0102", 67, 68), ("NX-E0102", 74, 78)]),
    "X_08_outer_condition_equiv": ("fn Main(){let a:I64=(if 0 then true else (if true then 1 else true));}", [("NX-E0102", 24, 25), ("NX-E0102", 31, 35), ("NX-E0102", 62, 66)]),
    "SB_equivalent": ("fn Main(){let p=true;let ar=[1];var r=[];var s=[];let a0=(if p then (if ar then r else ar) else s);}", [("NX-E0102", 72, 74), ("NX-E0103", 47, 49)]),
    "T5_constructor_equivalent": ("fn Main(){let p=true;var q=[];var r=[];let a0=[q,(if p then q else (if q then true else [r]))];}", [("NX-E0103", 36, 38)]),
    "S_A_independent_constructor_equiv": ("fn Main(){var q=[];let z=true+1;}", [("NX-E0103", 16, 18), ("NX-E0102", 25, 29)]),
    "recursive_69": ("fn Main(){var v=(if true then {return;}else{return;});var a=[v];v=a;}", [("NX-E0103", 60, 63)]),
    "recursive_78_equivalent": ("fn Main(){var q=[];var v=(if true then {return;}else{return;});var a=[v];v=a;}", [("NX-E0103", 16, 18), ("NX-E0103", 69, 72)]),
    "recursive_127_equivalent": ("fn Main(){var v=(if true then {return;}else{return;});var a=[v];v=a;var w=(if true then {return;}else{return;});var b=[w];w=b;}", [("NX-E0103", 60, 63), ("NX-E0103", 118, 121)]),
    "atomic_78": ("fn Main(){var r=[];var q=[];(if true then true else q);[r,q];q=[[true]];r=[];}", [("NX-E1303", 52, 53)]),
    "completion_conflict": ("fn Main(){var q=[];let a=[q,1];q=[true];}", [("NX-E0102", 28, 29)]),
    "completion_unresolved": ("fn Main(){var q=[];let a=[q,1];}", [("NX-E0103", 16, 18)]),
    "suspended_68": ("fn Main(){var q=[];var r=[];(if true then q else r);q=[1];r=[true];}", [("NX-E0102", 61, 65)]),
    "waiting_projection_valid": ("fn Main(){var q=(if true then {return;}else{return;});let a:Bool=q[0];q=[true];}", []),
    "waiting_projection_candidate_conflict": ("fn Main(){var q=(if true then {return;}else{return;});let a:Bool=q[0];q=[1];}", [("NX-E0102", 73, 74)]),
    "waiting_projection_refuted": ("fn Main(){var q=(if true then {return;}else{return;});let a:Bool=q[0];q=3;}", [("NX-E0102", 65, 66)]),
    "join_record": ("fn Main(){let p=true;let a=(if p then (if p then 1 else true) else [1]);}", [("NX-E1303", 56, 60), ("NX-E1303", 67, 70)]),
    "ST1_equivalent": ("fn Main(){var q=[];let a=[q[0],(if true then [q] else (if true then [1] else q))];q=[1];}", [("NX-E1303", 68, 71)]),
    "W1_atomic_compound": ("fn Main(){let p=true;let aar=[[1]];var q=[];var r=[];var s=[];(if p then (if p then (if p then (if 1 then aar else s[0]) else (if p then q[0] else q)) else (if p then [r,s] else (if p then q[0] else r))) else aar);q=aar;}", [("NX-E0102", 99, 100), ("NX-E1303", 147, 148), ("NX-E1303", 199, 200), ("NX-E1303", 209, 212), ("NX-E0102", 216, 219)]),
    "W1a_without_later_assignment": ("fn Main(){let p=true;let aar=[[1]];var q=[];var r=[];var s=[];(if p then (if p then (if p then (if 1 then aar else s[0]) else (if p then q[0] else q)) else (if p then [r,s] else (if p then q[0] else r))) else aar);}", [("NX-E0102", 99, 100), ("NX-E1303", 147, 148), ("NX-E1303", 199, 200), ("NX-E1303", 209, 212)]),
    "M2_partial_witness_chain": ("fn Main(){let p=true;let aar=[[1]];var q=[];(if p then (if p then (if p then (if 1 then true else false) else (if p then q[0] else q)) else [[true]]) else aar);}", [("NX-E0102", 81, 82), ("NX-E1303", 131, 132), ("NX-E1303", 155, 158)]),
    "RC1_read_context_variable": ("fn Main(){var s=[];let a=[s[0],(if true then 1 else true)];s=[1];}", [("NX-E1303", 52, 56)]),
    "RC2_read_context_committed": ("fn Main(){var q=[];q=[1];let a=[q[0],(if true then 1 else true)];}", [("NX-E0102", 58, 62)]),
    "RC3_read_context_no_retroactive": ("fn Main(){var q=[];let a=[q[0],(if true then 1 else true)];let b:I64=q[0];}", [("NX-E1303", 52, 56)]),
    "SU1_suspended_order": ("fn Main(){var q=[];var r=[];(if true then q else r);r=[true];q=[1];}", [("NX-E0102", 64, 65)]),
    "SU2_suspended_chain": ("fn Main(){var q=[];var r=[];var s=[];(if true then q else r);(if true then r else s);s=[1];q=[true];}", [("NX-E0102", 94, 98)]),
    "RS1_condition_contaminated": ("fn Main(){let a=(if true then (if 1 then true else false) else 2);}", [("NX-E0102", 34, 35)]),
    "RS2_independent_child_errors": ("fn Main(){let a=(if true then true+1 else (if true then 1 else true));}", [("NX-E0102", 30, 34), ("NX-E1303", 63, 67)]),
    "RS3_partial_in_array": ("fn Main(){let a=[(if true then 1 else true),[1]];}", [("NX-E1303", 38, 42)]),
    "CD1_independent_constructor": ("fn Main(){var q=[];var r=[];let a=[q,1];r=[true];}", [("NX-E0103", 16, 18)]),
    "CD2_independent_error_and_duties": ("fn Main(){var q=[];var r=[];(if true then q else r);let z=true+1;}", [("NX-E0103", 16, 18), ("NX-E0103", 25, 27), ("NX-E0102", 58, 62)]),
    # A's ADR derivation: E0103 [77,79) in place of main's E0102 [85,86).
    # The E1303 in a1 is independent. B has not yet validated this oracle.
    "W2_no_retroactive_context": ("fn Main(){let p=true;let aar=[[1]];var q=[];var r=[];let a0=[r[0],(if p then [] else 1)];let a1=[(if p then q[0] else (if p then (if p then [[q]] else aar) else r)),1];}", [("NX-E0103", 77, 79), ("NX-E1303", 140, 145)]),
}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("exe", type=Path)
    parser.add_argument("--profile", default="f0-0002-b-v2")
    parser.add_argument("--flags", default=None)
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()
    env = os.environ.copy()
    if args.flags is not None:
        env["NEXO_XV"] = args.flags
    binary = args.exe.resolve()
    binary_sha256 = hashlib.sha256(binary.read_bytes()).hexdigest()
    rows = []
    fixture = Path(__file__).resolve().parent.parent / "docs/validation/i07c-rediseno/b3-acceptance.json"
    acceptance = json.loads(fixture.read_text(encoding="utf-8"))
    if len(acceptance) != 35:
        raise ValueError("B round-3 acceptance fixture must have 35 cases")
    with tempfile.TemporaryDirectory(prefix="i07c-r6-", dir="C:/nexo-work/tmp") as directory:
        all_cases = dict(CASES)
        for item in acceptance:
            if item["bytes"] != len(item["source"].encode("ascii")):
                raise ValueError((item["id"], "byte length changed"))
            all_cases["B3_" + item["id"]] = (
                item["source"],
                [(d["code"], d["start"], d["end"]) for d in item["expected"]],
            )
        for name, (source, expected) in all_cases.items():
            path = Path(directory) / (name + ".n")
            path.write_bytes(source.encode("ascii"))
            completed = subprocess.run(
                [str(binary), "check", "--format", "json", "--profile", args.profile, str(path)],
                capture_output=True, text=True, env=env, timeout=60,
            )
            try:
                payload = json.loads(completed.stdout)
                outcome = payload.get("outcome") or {}
                if (payload.get("driver_error") is not None
                        or payload.get("internal_error") is not None
                        or outcome.get("kind") not in ("checked", "rejected")):
                    raise ValueError(f"abnormal outcome: {outcome!r}; driver_error={payload.get('driver_error')!r}; internal_error={payload.get('internal_error')!r}")
                actual = [(d["code"], d["primary_span"]["start"], d["primary_span"]["end"])
                          for d in payload["diagnostics"]]
                detail = [{"code": d["code"], "subcause": d.get("subcause"),
                           "primary": [d["primary_span"]["start"], d["primary_span"]["end"]],
                           "related": [(r["role"], r["span"]["start"], r["span"]["end"])
                                       for r in d.get("related_spans", [])],
                           "data": d.get("data", {})} for d in payload["diagnostics"]]
                error = None
            except (KeyError, TypeError, ValueError) as exc:
                actual = None
                detail = None
                error = f"{exc}: {completed.stdout[-200:]} {completed.stderr[-200:]}"
            rows.append({"name": name, "bytes": len(source), "source": source,
                         "expected": expected, "actual": actual, "observed_detail": detail,
                         "matches": None if expected is None else (
                             sorted(actual, key=lambda item: (item[1], item[2], item[0]))
                             == sorted(expected, key=lambda item: (item[1], item[2], item[0]))
                         ) if actual is not None else False,
                         "exit": completed.returncode,
                         "error": error})
    report = {"binary": str(binary), "binary_sha256": binary_sha256,
              "profile": args.profile, "flags": args.flags, "fixture": str(fixture), "rows": rows}
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    for row in rows:
        verdict = "UNADJUDICATED" if row["matches"] is None else ("MATCH" if row["matches"] else "DIFF")
        print(f"{row['name']}: {verdict} {row['actual']}")
    if any(row["matches"] is False for row in rows):
        raise SystemExit(1)
    if any(row["matches"] is None for row in rows):
        raise SystemExit(2)


if __name__ == "__main__":
    main()
